which node && node -e "
const Database = require('better-sqlite3');
" 2>&1 || true
# Try using node with sqlite
node -e "
const fs = require('fs');
// Check if we can read the db file at all
const buf = fs.readFileSync('/workspace/world.db');
console.log('DB size:', buf.length, 'bytes');
" 2>&1

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// List tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

// Check users for James Okafor (E002 - the BostonTech traveler)
const users = db.prepare(\"SELECT user_id, name, email, loyalty_tier, address_json FROM users WHERE skill_ids_json LIKE '%tau2Airline%'\").all();
for (const u of users) {
  const addr = JSON.parse(u.address_json || '{}');
  console.log(u.user_id, '|', u.name, '|', u.email, '| tier:', u.loyalty_tier, '| city:', addr.city, addr.state);
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Find James Okafor in all users
const james = db.prepare(\"SELECT * FROM users WHERE name LIKE '%James%' OR name LIKE '%Okafor%'\").all();
console.log('James Okafor matches:', james.length);
james.forEach(u => console.log(u.user_id, u.name, u.email));

// Also check what airports are near Portland (PDX? or maybe the origin city)
// Let's look at flights to BOS
const flights = db.prepare(\"SELECT * FROM flights WHERE destination='BOS' AND source_skill='tau2Airline'\").all();
console.log('\nDirect flights to BOS:', flights.length);
flights.forEach(f => {
  console.log(f.flight_id, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time);
});

// Also check all origins
const origins = db.prepare(\"SELECT DISTINCT origin FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('\nAll origins:', origins.map(o => o.origin));

// All destinations
const dests = db.prepare(\"SELECT DISTINCT destination FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('All destinations:', dests.map(d => d.destination));
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// No direct flights to BOS. Let's look at ALL flights
const flights = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('Total flights:', flights.length);
flights.forEach(f => {
  const dates = JSON.parse(f.dates_json || '{}');
  const avail = Object.entries(dates).filter(([d, s]) => s.status === 'available').map(([d, s]) => d + ' prices:' + JSON.stringify(s.prices));
  console.log(f.flight_id, f.origin, '->', f.destination, 'dep:', f.departure_time, 'arr:', f.arrival_time);
  avail.forEach(a => console.log('  ', a));
});
"

